tool_input.command:
cat >> db/schema.ts <<'EOF'

export const tags = sqliteTable('tags', {
  id: integer('id').primaryKey({ autoIncrement: true }),
  name: text('name').notNull().unique(),
})

export const postTags = sqliteTable(
  'post_tags',
  {
    id: integer('id').primaryKey({ autoIncrement: true }),
    postId: integer('post_id')
      .notNull()
      .references(() => posts.id, { onDelete: 'cascade' }),
    tagId: integer('tag_id')
      .notNull()
      .references(() => tags.id, { onDelete: 'cascade' }),
  },
  (table) => [uniqueIndex('post_tags_post_id_tag_id_unique').on(table.postId, table.tagId)],
)
EOF
sed -i.bak "1s/.*/import { sqliteTable, integer, text, uniqueIndex } from '@guren\/orm\/drizzle\/sqlite'/" db/schema.ts; rm db/schema.ts.bak
cat > app/Models/Tag.ts <<'EOF'
import { defineModel } from '@guren/core'
import { tags } from '../../db/schema.js'

export type TagRecord = typeof tags.$inferSelect

export class Tag extends defineModel(tags, {
  fillable: ['name'],
}) {}
EOF
cat > app/Models/PostTag.ts <<'EOF'
import { defineModel } from '@guren/core'
import { postTags } from '../../db/schema.js'

export class PostTag extends defineModel(postTags, {
  fillable: ['postId', 'tagId'],
}) {}
EOF
bunx guren make:migration post_tags 2>&1 | tail -5; ls db/migrations; grep -rn "foreign_keys\|PRAGMA" config src app 2>/dev/null | head
